from pathlib import Path
import re, os, json

ROOT = Path(__file__).resolve().parent.parent
WORK = ROOT / '_WORK'
FILES = {p.name.split('_')[0]: p for wave in ['W1','W2'] for p in (WORK/wave).glob('*.md')}
TEXT = {k:p.read_text(encoding='utf-8') for k,p in FILES.items()}
sources=[]; smap={}; facts=[]; fmap={}; qmap={}; emap={}

def source(aliases,title,author,url,version,loc,files,status,scope,caveat):
    sid=f'S{len(sources)+1:03d}'
    for a in aliases.split(): smap[a]=sid
    sources.append(dict(id=sid,title=title,author=author,url=url,version=version,loc=loc,files=files,status=status,scope=scope,caveat=caveat))
    return sid

