def getsection(branch,local):
    text=TEXT[branch]
    pat=rf'(?m)^###?\s+{re.escape(branch)}-F{local:02d}\b[^\n]*\n'
    m=re.search(pat,text)
    if not m: # W1B F13 has no heading
        m=re.search(rf'(?m)^{branch}-F{local:02d}\b[^\n]*',text)
    if not m: raise ValueError((branch,local))
    rest=text[m.end():]
    end=re.search(r'(?m)^#{2,3}\s',rest)
    return m.group().strip().lstrip('# ').strip(),rest[:end.start() if end else len(rest)].strip()

def fact(branch,n,group,src,kind=None,extra=''):
    fid=f'F{len(facts)+1:03d}'
    title,body=getsection(branch,n)
    fmap[f'{branch}-F{n:02d}']=fid
    title=re.sub(r'^'+branch+r'-F\d+[. —–]*','',title).strip()
    facts.append(dict(id=fid,origin=f'{branch}-F{n:02d}',branch=branch,group=group,title=title,body=body,src=src,kind=kind,extra=extra))
    return fid

