def norm_links(text,branch):
    base=FILES[branch].parent
    def change(m):
        label,url=m.groups()
        if re.match(r'https?://|mailto:|#',url): return m.group()
        path,sep,anchor=url.partition('#')
        target=(base/path).resolve()
        rel=os.path.relpath(target,ROOT).replace('\\','/')
        return f'[{label}]({rel}{sep}{anchor})'
    return re.sub(r'\[([^\]]*)\]\(([^)]+)\)',change,text)

def canon(text,branch):
    # Preserve named neighbouring topics. Canonicalize explicit wave IDs first.
    text=norm_links(text,branch)
    def expand_range(owner,typ,lo,hi):
        registry=smap if typ=='S' else fmap
        values=[]
        for number in range(int(lo),int(hi)+1):
            value=registry.get(f'{owner}-{typ}{number:02d}',f'{owner}-{typ}{number:02d}')
            values.extend(value.split(', '))
        return ', '.join(dict.fromkeys(values))
    # Expand a neighbouring branch's shorthand before the local bare-ID pass:
    # W1A-F14–F16,F20 and F07/F17 W1A retain W1A ownership throughout.
    run=r'[SF]\d{2}(?!\d)(?:(?:\s*[–—]\s*[SF]?\d{2}(?!\d))|(?:\s*[/,]\s*[SF]\d{2}(?!\d)))*'
    def scoped(m):
        owner,ids=m.groups()
        ids=re.sub(r'([SF])(\d{2})(?!\d)\s*[–—]\s*(?:[SF])?(\d{2})(?!\d)',lambda z:expand_range(owner,z[1],z[2],z[3]),ids)
        return re.sub(r'([SF])(\d{2})(?!\d)',lambda z:(smap if z[1]=='S' else fmap).get(f'{owner}-{z[1]}{z[2]}',f'{owner}-{z[1]}{z[2]}'),ids)
    text=re.sub(r'\b(W[12][A-F])[-:/ ]+('+run+r')',scoped,text)
    def suffix(m): return scoped(type('M',(),{'groups':lambda self:(m[2],m[1])})())
    text=re.sub(r'('+run+r')\s+(W[12][A-F])\b',suffix,text)
    text=re.sub(r'(?<![\w:])([SF])(\d{2})(?!\d)\s*[–—]\s*(?:[SF])?(\d{2})(?!\d)',
        lambda m:expand_range(branch,m[1],m[2],m[3]),text)
    for a,v in sorted({**smap,**fmap}.items(),key=lambda kv:-len(kv[0])):
        for old in [a,a.replace('-',':')]:
            text=re.sub(r'(?<![\w])'+re.escape(old)+r'(?![\w])',v,text)
    # Bare two-digit branch-local IDs only. Named other research IDs are three digits.
    def bare(m):
        typ,num=m.groups(); a=f'{branch}-{typ}{num}'
        return (smap if typ=='S' else fmap).get(a,a)
    text=re.sub(r'(?<![\w:])([SF])(\d{2})(?!\d)',bare,text)
    # Final text uses short quotations only. The exact UI field is unnecessary here.
    text=text.replace('«Выберите презентующего для защиты решений»','поле выбора презентующего')
    text=text.replace('W2B-S06','журнал адресного поиска/атрибуции, локатор в provenance F046')
    text=text.replace('S063/F','linq_platform:F').replace('S065/F','evaluation:F')
    text=text.replace('S065 F212–234','evaluation:F212–F234 (S065)')
    text=re.sub(r'(?<![\w/])SOURCES/W','_WORK/SOURCES/W',text)
    text=re.sub(r'\bturn\w+\b','[служебный идентификатор исключён]',text)
    return text

