def link_ids(s,filename):
    return ', '.join(f'[{i}]({filename}#{i.lower()})' for i in re.findall(r'\b[SFQKE]\d{3}\b',s))

def source_links(s): return link_ids(s,'SOURCES.md')
def fact_links(s): return link_ids(s,'RAW_FACTS.md')

def readable(text):
    # Typography for our prose; URL/path and all exact English/code identifiers
    # remain untouched. In particular digit-dot versions are not split.
    text=re.sub(r';(?=\S)','; ',text)
    text=re.sub(r',(?=[А-Яа-яЁёA-Za-z])',', ',text)
    text=re.sub(r'([А-Яа-яЁё])([A-Za-z0-9])',r'\1 \2',text)
    text=re.sub(r'([A-Za-z0-9])([А-Яа-яЁё])',r'\1 \2',text)
    return text

